    32	rawspeed::RawImage CreateRawImage(rawspeed::ByteStream* bs) {
    33	  assert(bs);
    34	
    35	  const rawspeed::uint32 width = bs->getU32();
    36	  const rawspeed::uint32 height = bs->getU32();
    37	  const rawspeed::uint32 type = bs->getU32();
    38	  const rawspeed::uint32 cpp = bs->getU32();
    39	  const rawspeed::uint32 isCFA = bs->getU32();
    40	
    41	  if (type != rawspeed::TYPE_USHORT16 && type != rawspeed::TYPE_FLOAT32)
    42	    ThrowRSE("Unknown image type: %u", type);
    43	
    44	  rawspeed::RawImage mRaw(
    45	      rawspeed::RawImage::create(rawspeed::RawImageType(type)));
    46	
    47	  mRaw->dim = rawspeed::iPoint2D(width, height);
    48	  mRaw->setCpp(cpp);
    49	  mRaw->isCFA = isCFA;
    50	
    51	  return mRaw;
    52	}
    53	
    54	rawspeed::ColorFilterArray CreateCFA(rawspeed::ByteStream* bs) {
    55	  assert(bs);
    56	
    57	  const rawspeed::uint32 cfaWidth = bs->getU32();
    58	  const rawspeed::uint32 cfaHeight = bs->getU32();
    59	
    60	  rawspeed::ColorFilterArray cfa;
    61	
    62	  if (cfaHeight &&
    63	      cfaWidth > std::numeric_limits<decltype(cfaWidth)>::max() / cfaHeight)
    64	    ThrowIOE("Integer overflow when calculating CFA area");
    65	  bs->check(cfaWidth * cfaHeight, 4);
    66	
    67	  cfa.setSize(rawspeed::iPoint2D(cfaWidth, cfaHeight));
    68	
    69	  for (auto x = 0U; x < cfaWidth; x++) {
    70	    for (auto y = 0U; y < cfaHeight; y++) {
    71	      const rawspeed::uint32 color = bs->getU32();
    72	      if (color >= static_cast<rawspeed::uint32>(rawspeed::CFA_END))
    73	        ThrowRSE("Unknown color: %u", color);
    74	
    75	      cfa.setColorAt(rawspeed::iPoint2D(x, y), rawspeed::CFAColor(color));
    76	    }
    77	  }
    78	
    79	  return cfa;
    80	}
